from collections import Counter


def transform(grid):
    """Reduce each 3x3 patch to its dominant foreground color.

    The recurring 5 and 0 are the two canvas/background colors; the output
    uses 0 for patches containing neither motif color.  Foreground colors
    are encoded by the most frequent non-background value in each patch.
    """
    h, w = len(grid), len(grid[0])
    if h % 3 or w % 3 or any(len(row) != w for row in grid):
        raise ValueError("grid must be rectangular with dimensions divisible by 3")
    out = []
    for br in range(0, h, 3):
        row = []
        for bc in range(0, w, 3):
            counts = Counter(
                grid[r][c]
                for r in range(br, br + 3)
                for c in range(bc, bc + 3)
                if grid[r][c] not in (0, 5)
            )
            row.append(min(counts, key=lambda color: (-counts[color], color)) if counts else 0)
        out.append(row)
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.loads(sys.stdin.read()))))", "exit_code": 0, "error": null}
